package com.orderflow.inventory; import com.orderflow.contracts.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Component; import java.time.Instant; import java.util.UUID;
@Component public class InventoryListener { private final InventoryRepository repo; private final KafkaTemplate<String,Object> kafka; public InventoryListener(InventoryRepository r,KafkaTemplate<String,Object> k){repo=r;kafka=k;} @KafkaListener(topics=Topics.INVENTORY,groupId="inventory") public void handle(SagaEvent e){ boolean ok=e.payload().products().stream().allMatch(p->p.quantity()<=10); InventoryReservation i=new InventoryReservation();i.orderId=e.orderId();i.status=ok?"RESERVED":"FAILED";repo.save(i);kafka.send(Topics.ORCHESTRATOR,e.orderId(),new SagaEvent(UUID.randomUUID().toString(),e.transactionId(),e.orderId(),SagaStep.INVENTORY,ok?SagaStatus.SUCCESS:SagaStatus.FAILED,ok?"Inventory reserved":"Insufficient inventory",e.payload(),Instant.now()));} }
